+}
+
+inline void primitiveFromConserved(const Conserved& q, double gamma, Primitive& w) {
+  const double rho = std::max(q.rho, 1e-300);
+  w.rho = q.rho;
+  w.u = q.rhou / rho;
+  w.v = q.rhov / rho;
+  const double kinetic = 0.5 * (q.rhou * q.rhou + q.rhov * q.rhov) / rho;
+  w.p = (gamma - 1.0) * (q.rhoE - kinetic);
+  w.T = w.p / (rho * 1.0);  / R = 1 in the supplied nondimensional cases
+}
