+inline Conserved conservedFromPrimitive(const Primitive& w, double gamma) {
+  Conserved q;
+  q.rho = w.rho;
+  q.rhou = w.rho * w.u;
+  q.rhov = w.rho * w.v;
+  const double e = w.p / ((gamma - 1.0) * std::max(w.rho, 1e-300));
+  q.rhoE = w.rho * (e + 0.5 * (w.u * w.u + w.v * w.v));
+  return q;
+}
