+  return {a.rho + b.rho, a.rhou + b.rhou, a.rhov + b.rhov, a.rhoE + b.rhoE};
+}
+
+inline Conserved sub(const Conserved& a, const Conserved& b) {
+  return {a.rho - b.rho, a.rhou - b.rhou, a.rhov - b.rhov, a.rhoE - b.rhoE};
+}
+
