+PartitionHeader readPartitionHeader(const std::string& path) {
+  std::ifstream in(path, std::ios::binary);
+  if (!in) throw std::runtime_error("cannot open partition file: " + path);
+  char magic[8];
+  in.read(magic, 8);
+  if (!in || std::memcmp(magic, kMagic, 8) != 0) throw std::runtime_error("bad partition file magic: " + path);
+  std::uint32_t version = 0, np = 0;
+  in.read(reinterpret_cast<char*>(&version), sizeof(version));
+  in.read(reinterpret_cast<char*>(&np), sizeof(np));
+  if (version != kVersion) throw std::runtime_error("unsupported partition file version");
+  if (np == 0 || np > 100000) throw std::runtime_error("invalid rank count in partition file");
+  PartitionHeader h;
+  h.np = static_cast<int>(np);
+  in.read(reinterpret_cast<char*>(&h.num_cells_global), sizeof(h.num_cells_global));
+  in.read(reinterpret_cast<char*>(&h.num_faces_global), sizeof(h.num_faces_global));
+  in.read(reinterpret_cast<char*>(&h.num_boundary_faces_global), sizeof(h.num_boundary_faces_global));
+  in.read(reinterpret_cast<char*>(&h.edge_cut), sizeof(h.edge_cut));
+  in.read(reinterpret_cast<char*>(&h.num_cells_global), sizeof(h.num_cells_global));  / 5th int64 placeholder is edge cut count slot
