+  h.offsets.resize(static_cast<std::size_t>(h.np));
+  h.sizes.resize(static_cast<std::size_t>(h.np));
+  in.read(reinterpret_cast<char*>(h.offsets.data()), static_cast<std::streamsize>(h.offsets.size() * sizeof(std::int64_t)));
+  in.read(reinterpret_cast<char*>(h.sizes.data()), static_cast<std::streamsize>(h.sizes.size() * sizeof(std::int64_t)));
+  if (!in) throw std::runtime_error("truncated partition header: " + path);
+  return h;
