+RankPartition readRankPartition(const std::string& path, int rank, PartitionHeader* header) {
+  PartitionHeader h = readPartitionHeader(path);
+  if (rank < 0 || rank >= h.np) throw std::runtime_error("rank index outside partition file");
+  if (header != nullptr) *header = h;
+  std::ifstream in(path, std::ios::binary);
+  if (!in) throw std::runtime_error("cannot open partition file: " + path);
