+double Solver::faceSpectralRadius(const Primitive& a, const Primitive& b, const Vec2& n) const {
+  const double una = a.u * n.x + a.v * n.y;
+  const double unb = b.u * n.x + b.v * n.y;
+  const double aa = std::sqrt(std::max(cfg_.gamma * a.p / std::max(a.rho, 1e-300), 0.0));
+  const double ab = std::sqrt(std::max(cfg_.gamma * b.p / std::max(b.rho, 1e-300), 0.0));
+  return std::max(std::abs(una) + aa, std::abs(unb) + ab);
+}
