+double Solver::viscousLambdaFace(const Primitive& a, const Primitive& b, const LocalFaceRec& f) const {
+  if (!cfg_.laminar()) return 0.0;
+  const double rho_face = std::max(0.5 * (a.rho + b.rho), 1e-12 * cfg_.rho_inf);
+  const double nu = cfg_.mu / rho_face;
+  return std::max(4.0 / 3.0, cfg_.gamma / cfg_.prandtl) * nu;
+}
