+void Solver::faceViscousGradient(const std::array<Vec2, NPRIM>& gL, const std::array<Vec2, NPRIM>& gR,
+                                 const Primitive& wL, const Primitive& wR, const LocalFaceRec& f,
+                                 double grad_u[2], double grad_v[2], double grad_T[2], double& div) const {
+  for (int k = 0; k < NPRIM; ++k) {
+    const Vec2 gm = 0.5 * (gL[static_cast<std::size_t>(k)] + gR[static_cast<std::size_t>(k)]);
+    double phiL = 0.0, phiR = 0.0;
+    switch (k) {
+      case 0: phiL = wL.rho; phiR = wR.rho; break;
+      case 1: phiL = wL.u; phiR = wR.u; break;
+      case 2: phiL = wL.v; phiR = wR.v; break;
+      case 3: phiL = wL.p; phiR = wR.p; break;
+      case 4: phiL = wL.T; phiR = wR.T; break;
+    }
+    const double corr = (phiR - phiL - dot(gm, f.d)) / f.dn;
+    const Vec2 gf = gm + corr * f.normal;
+    if (k == 1) { grad_u[0] = gf.x; grad_u[1] = gf.y; }
+    if (k == 2) { grad_v[0] = gf.x; grad_v[1] = gf.y; }
+    if (k == 4) { grad_T[0] = gf.x; grad_T[1] = gf.y; }
+  }
+  div = grad_u[0] + grad_v[1];
+}
