+void Solver::computeWallTraction(int cell, int face_index, double& tau_x, double& tau_y) const {
+  tau_x = 0.0;
+  tau_y = 0.0;
+  if (!cfg_.laminar()) return;
+  const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(face_index)];
+  if (f.bc_type != static_cast<int>(BcType::NoSlipAdiabaticWall)) return;
+  const Primitive& w = w_[static_cast<std::size_t>(cell)];
+  const Vec2 c = mesh_.cells[static_cast<std::size_t>(cell)].center;
+  const Vec2 d = f.center - c;
+  const double dn = dot(d, f.normal);
+  if (!(dn > 0.0)) throw std::runtime_error("wall face normal distance is not positive");
+  const Vec2& gu = grad_[static_cast<std::size_t>(cell)][1];
+  const Vec2& gv = grad_[static_cast<std::size_t>(cell)][2];
+  const Vec2 guf = gu + (((0.0 - w.u) - dot(gu, d)) / dn) * f.normal;
+  const Vec2 gvf = gv + (((0.0 - w.v) - dot(gv, d)) / dn) * f.normal;
+  const double div = guf.x + gvf.y;
+  const double mu = cfg_.mu;
+  const double txx = 2.0 * mu * guf.x - (2.0 / 3.0) * mu * div;
+  const double tyy = 2.0 * mu * gvf.y - (2.0 / 3.0) * mu * div;
+  const double txy = mu * (guf.y + gvf.x);
+  tau_x = txx * f.normal.x + txy * f.normal.y;
+  tau_y = txy * f.normal.x + tyy * f.normal.y;
+}
