+void Solver::jacobianTimes(const Primitive& w, const Vec2& n, const Conserved& dU, Conserved& out) const {
+  const double gamma = cfg_.gamma;
+  const double u = w.u, v = w.v;
+  const double qn = u * n.x + v * n.y;
+  const double beta = 0.5 * (gamma - 1.0) * (u * u + v * v);
+  const double H = gamma * w.p / ((gamma - 1.0) * std::max(w.rho, 1e-300)) + 0.5 * (u * u + v * v);
+  out.rho = n.x * dU.rhou + n.y * dU.rhov;
+  out.rhou = (-qn * u + n.x * beta) * dU.rho +
+             (u * n.x + qn - n.x * (gamma - 1.0) * u) * dU.rhou +
+             (u * n.y - n.x * (gamma - 1.0) * v) * dU.rhov +
+             n.x * (gamma - 1.0) * dU.rhoE;
+  out.rhov = (-qn * v + n.y * beta) * dU.rho +
+             (v * n.x - n.y * (gamma - 1.0) * u) * dU.rhou +
+             (v * n.y + qn - n.y * (gamma - 1.0) * v) * dU.rhov +
+             n.y * (gamma - 1.0) * dU.rhoE;
+  out.rhoE = qn * beta * dU.rho +
+             (H * n.x - qn * (gamma - 1.0) * u) * dU.rhou +
+             (H * n.y - qn * (gamma - 1.0) * v) * dU.rhov +
+             gamma * qn * dU.rhoE;
+}
