+      residual[static_cast<std::size_t>(i)].rhov += (1.5 * ucur.rhov - 2.0 * un.rhov + 0.5 * un1.rhov) / dt_phys_;
+      residual[static_cast<std::size_t>(i)].rhoE += (1.5 * ucur.rhoE - 2.0 * un.rhoE + 0.5 * un1.rhoE) / dt_phys_;
+    }
+  }
+}
+
+void Solver::computeResidualNorms(const std::vector<Conserved>& residual, double out_l2[NVAR],
+                                  double& out_total_l2, double& out_linf) const {
+  double local_sum[NVAR] = {0.0, 0.0, 0.0, 0.0};
+  double local_vol = 0.0;
+  double local_max = 0.0;
+  for (int i = 0; i < mesh_.nOwned(); ++i) {
+    const Conserved& r = residual[static_cast<std::size_t>(i)];
+    const double vol = mesh_.cells[static_cast<std::size_t>(i)].vol;
+    local_sum[0] += r.rho * r.rho * vol;
+    local_sum[1] += r.rhou * r.rhou * vol;
+    local_sum[2] += r.rhov * r.rhov * vol;
+    local_sum[3] += r.rhoE * r.rhoE * vol;
+    local_vol += vol;
+    local_max = std::max(local_max, maxAbs4(r));
+  }
+  double global_sum[NVAR] = {0.0, 0.0, 0.0, 0.0};
+  double global_vol = 0.0, global_max = 0.0;
+  MPI_Allreduce(local_sum, global_sum, NVAR, MPI_DOUBLE, MPI_SUM, MPI_COMM_WORLD);
+  MPI_Allreduce(&local_vol, &global_vol, 1, MPI_DOUBLE, MPI_SUM, MPI_COMM_WORLD);
+  MPI_Allreduce(&local_max, &global_max, 1, MPI_DOUBLE, MPI_MAX, MPI_COMM_WORLD);
+  if (!(global_vol > 0.0)) throw std::runtime_error("zero global volume");
+  double total2 = 0.0;
+  for (int k = 0; k < NVAR; ++k) {
+    out_l2[k] = std::sqrt(std::max(0.0, global_sum[k]) / global_vol);
+    total2 += std::max(0.0, global_sum[k]) / global_vol;
+  }
+  out_total_l2 = std::sqrt(total2);
+  out_linf = global_max;
+}
+
+void Solver::computeLocalPseudoTime(double cfl, std::vector<double>& dt_local) const {
+  const int nOwned = mesh_.nOwned();
+  dt_local.assign(static_cast<std::size_t>(nOwned), 0.0);
+  for (int i = 0; i < nOwned; ++i) {
+    double sum = 0.0;
+    for (int fi : mesh_.cell_faces[static_cast<std::size_t>(i)]) {
+      const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+      const Primitive& a = w_[static_cast<std::size_t>(i)];
+      Primitive b;
+      if (f.right >= 0) {
+        b = primitiveAny(f.right);
+      } else {
+        b = wbc_[static_cast<std::size_t>(bface_pos_[static_cast<std::size_t>(fi)])];
+      }
+      sum += faceSpectralRadius(a, b, f.normal) * f.area;
+    }
+    dt_local[static_cast<std::size_t>(i)] = cfl * mesh_.cells[static_cast<std::size_t>(i)].vol / std::max(sum, 1e-30);
+  }
+}
+
+double Solver::positivityAlpha(const std::vector<Conserved>& delta) const {
+  const double floor_rho = 1e-8 * cfg_.rho_inf;
+  const double floor_p = 1e-8 * cfg_.p_inf;
+  auto valid = [&](double alpha) {
+    for (int i = 0; i < mesh_.nOwned(); ++i) {
+      const Conserved& u = state_.u[static_cast<std::size_t>(i)];
+      const Conserved& d = delta[static_cast<std::size_t>(i)];
+      const double rho = u.rho + alpha * d.rho;
+      const double rhou = u.rhou + alpha * d.rhou;
+      const double rhov = u.rhov + alpha * d.rhov;
+      const double rhoE = u.rhoE + alpha * d.rhoE;
+      if (!(rho > floor_rho) || !std::isfinite(rho) || !std::isfinite(rhou) || !std::isfinite(rhov) || !std::isfinite(rhoE)) return false;
+      const double p = (cfg_.gamma - 1.0) * (rhoE - 0.5 * (rhou * rhou + rhov * rhov) / rho);
+      if (!(p > floor_p) || !std::isfinite(p)) return false;
+    }
+    return true;
+  };
+  if (valid(1.0)) return 1.0;
+  double alpha = 1.0;
+  for (int k = 0; k < 24; ++k) {
+    alpha *= 0.5;
+    if (valid(alpha)) return alpha;
+  }
+  return 0.0;
+}
+
+void Solver::applyUpdate(const std::vector<Conserved>& delta, double alpha) {
+  if (alpha <= 0.0) return;
+  for (int i = 0; i < mesh_.nOwned(); ++i) {
+    addScaled(state_.u[static_cast<std::size_t>(i)], delta[static_cast<std::size_t>(i)], alpha);
+  }
+}
+
+void Solver::luSgsUpdate(const std::vector<Conserved>& residual, const std::vector<double>& dt_local,
+                         bool include_physical_time) {
+  const int nOwned = mesh_.nOwned();
+  const int nf = static_cast<int>(mesh_.faces.size());
+  std::vector<double> lambda(static_cast<std::size_t>(nf), 0.0);
+  std::vector<double> diag(static_cast<std::size_t>(nOwned), 0.0);
+  for (int fi = 0; fi < nf; ++fi) {
+    const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+    const Primitive& a = w_[static_cast<std::size_t>(f.left)];
+    Primitive b;
+    if (f.right >= 0) b = primitiveAny(f.right);
+    else b = wbc_[static_cast<std::size_t>(bface_pos_[static_cast<std::size_t>(fi)])];
+    lambda[static_cast<std::size_t>(fi)] = faceSpectralRadius(a, b, f.normal);
+  }
+  for (int i = 0; i < nOwned; ++i) {
+    double d = mesh_.cells[static_cast<std::size_t>(i)].vol / std::max(dt_local[static_cast<std::size_t>(i)], 1e-300);
+    if (include_physical_time && dt_phys_ > 0.0) {
+      d += 1.5 * mesh_.cells[static_cast<std::size_t>(i)].vol / dt_phys_;
+    }
+    for (int fi : mesh_.cell_faces[static_cast<std::size_t>(i)]) {
+      const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+      d += 0.5 * lambda[static_cast<std::size_t>(fi)] * f.area;
+      if (cfg_.laminar()) {
+        const Primitive& a = w_[static_cast<std::size_t>(f.left)];
+        Primitive b;
+        if (f.right >= 0) b = primitiveAny(f.right);
+        else b = wbc_[static_cast<std::size_t>(bface_pos_[static_cast<std::size_t>(fi)])];
+        const double nu_eff = viscousLambdaFace(a, b, f);
+        d += nu_eff * f.area / std::max(f.dn, 1e-30);
+      }
+    }
+    diag[static_cast<std::size_t>(i)] = std::max(d, 1e-30);
+  }
+
+  std::vector<Conserved> dstar(static_cast<std::size_t>(nOwned)), delta(static_cast<std::size_t>(nOwned));
+  for (int i = 0; i < nOwned; ++i) {
+    const double vol = mesh_.cells[static_cast<std::size_t>(i)].vol;
+    Conserved rhs = scaled(residual[static_cast<std::size_t>(i)], -vol);
+    for (int fi : mesh_.cell_faces[static_cast<std::size_t>(i)]) {
+      const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+      Vec2 nout;
+      int j = -1;
+      if (f.left == i) { j = f.right; nout = f.normal; }
+      else { j = f.left; nout = -1.0 * f.normal; }
+      if (j >= 0 && j < nOwned && j < i) {
+        Conserved Adu;
+        jacobianTimes(w_[static_cast<std::size_t>(j)], nout, delta[static_cast<std::size_t>(j)], Adu);
+        const double lam = lambda[static_cast<std::size_t>(fi)];
+        Conserved c;
+        c.rho = 0.5 * (Adu.rho - lam * delta[static_cast<std::size_t>(j)].rho) * f.area;
+        c.rhou = 0.5 * (Adu.rhou - lam * delta[static_cast<std::size_t>(j)].rhou) * f.area;
+        c.rhov = 0.5 * (Adu.rhov - lam * delta[static_cast<std::size_t>(j)].rhov) * f.area;
+        c.rhoE = 0.5 * (Adu.rhoE - lam * delta[static_cast<std::size_t>(j)].rhoE) * f.area;
+        rhs = sub(rhs, c);
+      }
+    }
+    dstar[static_cast<std::size_t>(i)] = scaled(rhs, 1.0 / diag[static_cast<std::size_t>(i)]);
+  }
+
+  for (int i = nOwned - 1; i >= 0; --i) {
+    Conserved rhs = scaled(dstar[static_cast<std::size_t>(i)], diag[static_cast<std::size_t>(i)]);
+    for (int fi : mesh_.cell_faces[static_cast<std::size_t>(i)]) {
+      const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+      Vec2 nout;
+      int j = -1;
+      if (f.left == i) { j = f.right; nout = f.normal; }
+      else { j = f.left; nout = -1.0 * f.normal; }
+      if (j >= 0 && j < nOwned && j > i) {
+        Conserved Adu;
+        jacobianTimes(w_[static_cast<std::size_t>(j)], nout, delta[static_cast<std::size_t>(j)], Adu);
+        const double lam = lambda[static_cast<std::size_t>(fi)];
+        Conserved c;
+        c.rho = 0.5 * (Adu.rho - lam * delta[static_cast<std::size_t>(j)].rho) * f.area;
+        c.rhou = 0.5 * (Adu.rhou - lam * delta[static_cast<std::size_t>(j)].rhou) * f.area;
+        c.rhov = 0.5 * (Adu.rhov - lam * delta[static_cast<std::size_t>(j)].rhov) * f.area;
+        c.rhoE = 0.5 * (Adu.rhoE - lam * delta[static_cast<std::size_t>(j)].rhoE) * f.area;
+        rhs = sub(rhs, c);
+      }
+    }
+    delta[static_cast<std::size_t>(i)] = scaled(rhs, 1.0 / diag[static_cast<std::size_t>(i)]);
+  }
+
+  / The forward/backward sweeps use ghost corrections of zero, which is the
+  / standard rank-local LU-SGS approximation at partition interfaces.
+  const double alpha = positivityAlpha(delta);
+  applyUpdate(delta, alpha);
+}
+
+void Solver::computeForces(double& cl, double& cd, double& cmz, double& pdrag, double& vdrag,
+                           double& plift, double& vlift) {
+  double pd = 0.0, vd = 0.0, pl = 0.0, vl = 0.0, mz = 0.0;
+  for (int fi : bface_ids_) {
+    const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+    if (f.bc_type != static_cast<int>(BcType::SlipWall) &&
+        f.bc_type != static_cast<int>(BcType::NoSlipAdiabaticWall)) {
+      continue;
+    }
+    const Primitive wl = reconstructOwned(f.left, f.center);
+    const double pw = std::max(wl.p, 1e-12 * cfg_.p_inf);
+    double tx = 0.0, ty = 0.0;
+    computeWallTraction(f.left, fi, tx, ty);
+    const double fpx = pw * f.normal.x * f.area;
+    const double fpy = pw * f.normal.y * f.area;
+    const double fvx = -tx * f.area;
+    const double fvy = -ty * f.area;
+    pd += fpx;
+    pl += fpy;
+    vd += fvx;
+    vl += fvy;
+    const double dx = f.center.x - cfg_.ref_moment_x;
+    const double dy = f.center.y - cfg_.ref_moment_y;
+    mz += dx * (fpy + fvy) - dy * (fpx + fvx);
+  }
+  double loc[5] = {pd, vd, pl, vl, mz};
+  double glob[5] = {0, 0, 0, 0, 0};
+  MPI_Allreduce(loc, glob, 5, MPI_DOUBLE, MPI_SUM, MPI_COMM_WORLD);
+  pdrag = glob[0];
+  vdrag = glob[1];
+  plift = glob[2];
+  vlift = glob[3];
+  mz = glob[4];
+  const double qa = cfg_.q_inf * cfg_.ref_area;
+  cd = (pdrag + vdrag) / qa;
+  cl = (plift + vlift) / qa;
+  cmz = mz / (qa * cfg_.ref_length);
+}
+
+void Solver::computeSurfaceRows() {
+  surface_.clear();
+  std::vector<std::string> tags;
+  for (const auto& kv : cfg_.boundary_conditions) tags.push_back(kv.first);
+  for (int fi : bface_ids_) {
+    const LocalFaceRec& f = mesh_.faces[static_cast<std::size_t>(fi)];
+    if (f.bc_type != static_cast<int>(BcType::SlipWall) &&
+        f.bc_type != static_cast<int>(BcType::NoSlipAdiabaticWall)) {
+      continue;
+    }
+    const Primitive wl = reconstructOwned(f.left, f.center);
+    SurfaceRow row;
+    row.x = f.center.x;
+    row.y = f.center.y;
+    row.nx = f.normal.x;
+    row.ny = f.normal.y;
+    row.pressure = std::max(wl.p, 1e-12 * cfg_.p_inf);
+    row.cp = (row.pressure - cfg_.p_inf) / cfg_.q_inf;
+    if (f.bc_type == static_cast<int>(BcType::NoSlipAdiabaticWall)) {
+      row.u = 0.0;
+      row.v = 0.0;
+      row.mach = 0.0;
+      const Primitive& wc = w_[static_cast<std::size_t>(f.left)];
+      row.rho = row.pressure / (cfg_.R * std::max(wc.T, 1e-12));
+      double tx = 0.0, ty = 0.0;
+      computeWallTraction(f.left, fi, tx, ty);
+      const Vec2 uinf = cfg_.velocity_inf;
+      Vec2 t = uinf - dot(uinf, f.normal) * f.normal;
+      const double tn = norm(t);
+      if (tn > 1e-12) {
+        t = (1.0 / tn) * t;
+        row.cf = -(tx * t.x + ty * t.y) / std::max(cfg_.q_inf, 1e-300);
+      } else {
+        row.cf = 0.0;
+      }
+    } else {
+      const Vec2 c = mesh_.cells[static_cast<std::size_t>(f.left)].center;
+      const auto& g = grad_[static_cast<std::size_t>(f.left)];
+      const auto& ps = psi_[static_cast<std::size_t>(f.left)];
+      const Vec2 dx = f.center - c;
+      const double uf = w_[static_cast<std::size_t>(f.left)].u + ps[1] * dot(g[1], dx);
+      const double vf = w_[static_cast<std::size_t>(f.left)].v + ps[2] * dot(g[2], dx);
+      const double un = uf * f.normal.x + vf * f.normal.y;
+      row.u = uf - un * f.normal.x;
+      row.v = vf - un * f.normal.y;
+      row.rho = wl.rho;
+      const double aa = std::sqrt(std::max(cfg_.gamma * row.pressure / std::max(row.rho, 1e-300), 0.0));
+      row.mach = std::sqrt(row.u * row.u + row.v * row.v) / std::max(aa, 1e-300);
+      row.cf = 0.0;
+    }
+    if (f.bc_tag >= 0 && f.bc_tag < static_cast<int>(tags.size())) row.tag = tags[static_cast<std::size_t>(f.bc_tag)];
+    else row.tag = std::to_string(f.bc_tag);
+    surface_.push_back(row);
+  }
+}
