+double Solver::cflForStep(long long step) const {
+  if (transient_) return cfg_.run.cfl_initial;
+  if (cfg_.run.pseudo_cfl_ramp_steps <= 0) return cfg_.run.cfl_max;
+  const double f = std::min(1.0, static_cast<double>(std::max<long long>(0, step - 1)) /
+                                     static_cast<double>(cfg_.run.pseudo_cfl_ramp_steps));
+  return cfg_.run.cfl_initial + (cfg_.run.cfl_max - cfg_.run.cfl_initial) * f;
+}
