+    fr.step = step;
+    fr.physical_time = 0.0;
+    fr.cl = cl;
+    fr.cd = cd;
+    fr.cmz = cmz;
+    fr.pressure_drag = pd;
+    fr.viscous_drag = vd;
+    fr.pressure_lift = pl;
+    fr.viscous_lift = vl;
+    forces_.push_back(fr);
+
+    inner_stats_.steps += 1;
+    inner_stats_.inner_sum += updates;
+    inner_stats_.min_observed = std::min(inner_stats_.min_observed, updates);
+    inner_stats_.max_observed = std::max(inner_stats_.max_observed, updates);
+    final_residual_ = res;
+    final_time_ = 0.0;
+    cfl_final_ = cfl;
+    if (residuals_.size() == 1) initial_residual_ = res;
